class_name BattleGrid
extends Node2D
## Battle 1 renderer (prototype lane): draws terrain + height shading + unit tokens.

var data := {}
const CELL := 48.0
const LIFT := 10.0

func _ready() -> void:
	var f := FileAccess.open("res://data/battle01.json", FileAccess.READ)
	if f == null:
		push_error("BattleGrid: battle01.json not found")
		return
	data = JSON.parse_string(f.get_as_text())
	f.close()
	var label := get_node_or_null("../ForecastLabel")
	if label and data.has("units"):
		var names: Array = CTEngine.forecast(data["units"], 8)
		label.text = "BATTLE 1: DAXING ROAD AMBUSH\nNext turns:  " + " > ".join(names)
	queue_redraw()

func tier_at(x: int, y: int) -> int:
	var heights: Array = data["map"]["height"]
	if y < heights.size() and x < heights[y].size():
		return int(heights[y][x])
	return 1

func _draw() -> void:
	if data.is_empty():
		return
	var mapd: Dictionary = data["map"]
	var rows := int(mapd["rows"])
	var cols := int(mapd["cols"])
	var terr: Array = mapd["terrain"]
	for y in rows:
		var row: String = str(terr[y])
		for x in cols:
			var t := "."
			if x < row.length():
				t = row[x]
			var tier := tier_at(x, y)
			var col := Color.WHITE
			match t:
				"r":
					col = Color(0.78, 0.68, 0.46)
				"f":
					col = Color(0.16, 0.45, 0.18)
				"#":
					col = Color(0.48, 0.48, 0.52)
				_:
					col = Color.from_hsv(0.29, 0.34, 0.92 - 0.20 * (tier - 1))
			var lift := LIFT * (tier - 1)
			draw_rect(Rect2(x * CELL, y * CELL - lift, CELL - 2.0, CELL - 2.0), col)
			if t == "#":
				draw_rect(Rect2(x * CELL + 10.0, y * CELL - lift + 10.0, CELL - 22.0, CELL - 22.0), Color(0.6, 0.6, 0.64))
	for u in data["units"]:
		var p: Array = u["pos"]
		var tier := tier_at(int(p[0]), int(p[1]))
		var lift := LIFT * (tier - 1)
		var center := Vector2(p[0] * CELL + CELL / 2.0, p[1] * CELL + CELL / 2.0 - lift)
		var ucol := Color(0.25, 0.72, 0.30)
		if str(u["faction"]) == "yellow":
			ucol = Color(0.95, 0.80, 0.12)
		draw_circle(center, 15.0, ucol)
		draw_arc(center, 15.0, 0.0, TAU, 32, Color.BLACK, 2.0)
		if bool(u.get("boss", false)):
			draw_arc(center, 20.0, 0.0, TAU, 32, Color(0.85, 0.15, 0.10), 3.0)
		draw_string(ThemeDB.fallback_font, center + Vector2(-34.0, 36.0), str(u["name"]),
			HORIZONTAL_ALIGNMENT_CENTER, 68.0, 11, Color.WHITE)
